head.script:
scwin.fr_MktId = $c.lcp.fn_getMktId();
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Isu_cd = "", scwin.Isu_nm = "", scwin.fr_bz_procs_no = "", scwin.select_gubun = "3", scwin.today_dd = "", scwin.cal_dd = "", scwin.fst_dtect_dd = "", scwin.inq_dd = "", scwin.design_dd = "";
scwin.fr_SecuGrpId = $c.lcp.fn_getSecuGrpId($c.stf.InfoMenuID());
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(pan_Cmd_1);
        $c.libRoundPanel.PanelToGroupBox(pan_Cmd_2);
        $c.libRoundPanel.PanelToGroupBox(pan_Cmd_3);
        $c.libRoundPanel.PanelToGroupBox(pan_Cmd_4);
        $c.libRoundPanel.PanelToGroupBox(pan_Cmd_5);
        $c.libRoundPanel.PanelToGroupBox(pan_Cmd_6);
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09340.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    cmb_RegistType.hide();
    lbl_RegistType.hide();
    // showObj(img_Regist, false);

    await scwin.todayDd();
    await scwin.calDd();
    MaxTab_1.setSelectedTabIndex(1);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
