/**
 * @method
 * @name grd_1_OnDblClick
 * @description grd_1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_1_OnDblClick = async function(row, colid) {
    try {
        scwin.fr_bz_procs_no = dts_1.getCellData(row, "BZ_PROCS_NO");
        scwin.Isu_cd = dts_1.getCellData(row, "ISU_CD");
        scwin.Isu_nm = dts_1.getCellData(row, "ISU_NM");
        scwin.Isur_cd = dts_1.getCellData(row, "ISUR_CD");
        scwin.Isur_nm = "";
        scwin.fst_dtect_dd = dts_1.getCellData(row, "FST_DTEC_DD");
        scwin.inq_dd = edt_search_date_1.getValue();
        scwin.design_dd = scwin.inq_dd;
        if (scwin.fr_bz_procs_no === "") {
            scwin.fn_GetPar = scwin.getParNew;
            scwin.fn_SetPar = undefined;
        } else {
            scwin.fn_GetPar = scwin.getParUpdate;
            scwin.fn_SetPar = undefined;
        }
        await scwin.newCreateFrame1();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09340.grd_1_OnDblClick" });
    }
};

