/**
 * @method
 * @name grd_6_OnDblClick
 * @description grd_6 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_6_OnDblClick = async function(row, colid) {
    try {
        scwin.fr_bz_procs_no = dts_6.getCellData(row, "BZ_PROCS_NO");
        scwin.Isu_cd = dts_6.getCellData(row, "ISU_CD");
        scwin.Isu_nm = dts_6.getCellData(row, "ISU_NM");
        scwin.Isur_cd = dts_6.getCellData(row, "ISUR_CD");
        scwin.Isur_nm = dts_6.getCellData(row, "ISUR_NM");
        scwin.fst_dtect_dd = dts_6.getCellData(row, "FST_DTEC_DD");
        scwin.inq_dd = edt_search_date_6.getValue();
        scwin.design_dd = scwin.cal_dd;
        if (scwin.fr_bz_procs_no === "" && dts_6.getCellData(row, "HALT_DESNRELS_TP_CD") === "1") {
            // 종목해제인경우
            const sbmOptions = {
                id : "sbm_dset_haltRealese",
                action : "/listingCommon.do",
                ref : "",
                target : "dset_haltRealese=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            scwin.fr_bz_procs_no = dset_haltRealese.getCellData(1, "BZ_PROCS_NO");
            scwin.fn_GetPar = scwin.getParRelease;
            scwin.fn_SetPar = undefined;
        } else {
            scwin.fr_bz_procs_no = dts_6.getCellData(row, "BZ_PROCS_NO");
            if (scwin.fr_bz_procs_no === "") {
                scwin.fn_GetPar = scwin.getParNewTrdHalt;
                scwin.fn_SetPar = undefined;
            } else {
                scwin.fn_GetPar = scwin.getParUpdateTrdHalt; // 매매거래정지
                scwin.fn_SetPar = undefined;
            }
        }
        if (scwin.fr_bz_procs_no !== "") {
            await scwin.updateCreateFrameTrdHalt(dts_6.getCellData(row, "HALT_DESNRELS_TP_CD"), dts_6.getCellData(row, "TRD_HALT_STRT_DD"));
        } else {
            if (dts_6.getCellData(row, "HALT_DESNRELS_TP_CD") === '0') {
                // 정지
                if (cmb_RegistType.BindColVal !== '0') {
                    // 정지
                    cmb_RegistType.BindColVal = "2"; // 지정 및 해제

                }
                await scwin.newCreateFrameTrdHalt(cmb_RegistType.BindColVal, "");
            } else {
                cmb_RegistType.BindColVal = dts_6.getCellData(row, "HALT_DESNRELS_TP_CD");
                await scwin.newCreateFrameTrdHalt(dts_6.getCellData(row, "HALT_DESNRELS_TP_CD"), "");
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09340.grd_6_OnDblClick" });
    }
};

/**
 * @method
 * @name MaxTab_1_OnSelChanged
 * @description Max Tab 1 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_1_OnSelChanged = async function(nIndex) {
    try {
        switch (MaxTab_1.getSelectedTabIndex()) {
            case 1:
            case 2:
                img_Regist.hide();
                break;
            case 3:
            case 4:
            case 5:
            case 6:
                img_Regist.show("");
                break;
        }
        if (MaxTab_1.getSelectedTabIndex() === 6) {
            cmb_RegistType.show("");
            lbl_RegistType.show("");
        } else {
            cmb_RegistType.hide();
            lbl_RegistType.hide();
        }
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09340.MaxTab_1_OnSelChanged" });
    }
};

