/**
 * @method
 * @name img_Regist_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Regist_onclick = async function() {
    try {
        scwin.Isu_cd = "";
        scwin.Isu_nm = "";
        scwin.Isur_cd = "";
        scwin.Isur_nm = "";
        scwin.fst_dtect_dd = "";
        switch (MaxTab_1.getSelectedTabIndex()) {
            case 1:
                scwin.inq_dd = edt_search_date_1.getValue();
                scwin.design_dd = scwin.inq_dd;
                break;
            case 2:
                scwin.inq_dd = edt_search_date_2.getValue();
                scwin.design_dd = scwin.cal_dd;
                break;
            case 3:
                scwin.inq_dd = edt_search_date_3.getValue();
                scwin.design_dd = scwin.cal_dd;
                break;
            case 4:
                scwin.inq_dd = edt_search_date_4.getValue();
                scwin.design_dd = scwin.cal_dd;
                break;
            case 5:
                scwin.inq_dd = edt_search_date_5.getValue();
                scwin.design_dd = scwin.cal_dd;
                break;
            case 6:
                scwin.inq_dd = edt_search_date_6.getValue();
                scwin.design_dd = scwin.cal_dd;
                break;
        }
        if (scwin.inq_dd < scwin.today_dd) {
            await $c.win.alert("과거 조회일자인 경우 조회만 가능합니다.");
            return;
        }
        scwin.fn_GetPar = scwin.getParNew;
        scwin.fn_SetPar = undefined;
        switch (MaxTab_1.getSelectedTabIndex()) {
            case 1:
                await scwin.newCreateFrame1();
                break;
            case 2:
                await scwin.newCreateFrame2();
                break;
            case 3:
                await scwin.newCreateFrame3();
                break;
            case 4:
                await scwin.newCreateFrame4();
                break;
            case 5:
                await scwin.newCreateFrame5();
                break;
            case 6:
                await scwin.newCreateFrame6();
                break;
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09340.img_Regist_onclick" });
    }
};

