            } else {
                await $c.win.alert(NO_EXCEL_DATA);
            }
        } else if (MaxTab_1.getSelectedTabIndex() === 2) {
            if (dts_2.getRowCount() > 0) {
                $c.data.downloadGridViewExcel(grd_2, {fileName: $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "투자유의 지정예고", type: "8"});
            } else {
                await $c.win.alert(NO_EXCEL_DATA);
            }
        } else if (MaxTab_1.getSelectedTabIndex() === 3) {
            if (dts_3.getRowCount() > 0) {
                $c.data.downloadGridViewExcel(grd_3, {fileName: $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "투자유의 지정", type: "8"});
            } else {
                await $c.win.alert(NO_EXCEL_DATA);
            }
        } else if (MaxTab_1.getSelectedTabIndex() === 4) {
            if (dts_4.getRowCount() > 0) {
                $c.data.downloadGridViewExcel(grd_4, {fileName: $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "투자유의 지정연장", type: "8"});
            } else {
                await $c.win.alert(NO_EXCEL_DATA);
