        } else if (MaxTab_1.getSelectedTabIndex() === 5) {
            if (dts_5.getRowCount() > 0) {
                $c.data.downloadGridViewExcel(grd_5, {fileName: $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "투자유의 지정해제", type: "8"});
            } else {
