/**
 * @method
 * @name getParNewTrdHalt
 * @description 매매거래정지  신규 파라메터
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParNewTrdHalt = function(arrPar) {
    // 넘길 인수를 지정하는 펑션

    arrPar[0] = scwin.Isur_cd;
    arrPar[1] = scwin.Isur_nm;
    arrPar[2] = scwin.fr_SecuGrpId;
    arrPar[3] = scwin.fr_MktId;
    arrPar[4] = "";
    arrPar[5] = cmb_RegistType.BindColVal;
    arrPar[6] = ""; // 종목코드
    arrPar[7] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    arrPar[8] = scwin.fst_dtect_dd; // 최초지정일
    arrPar[9] = scwin.design_dd; // 매매거래정지일
    arrPar[10] = scwin.inq_dd; // 조회일
    arrPar[11] = "424";
    arrPar[12] = "투자유의종목(상장형 수익증권)";
    arrPar[13] = "";
    let remk = "";
    if (cmb_RegistType.BindColVal === "0") {
        // 매매거래정지 정지
        remk = "상기 종목은 시장상황급변 등으로 투자자보호 및 시장안정을 위하여 매매거래가 정지됩니다.\r\n" + "매매거래정지 해제 시 별도의 시장안내가 있을 예정이며,\r\n" + "매매거래 재개시 투자유의종목으로서 3매매거래일(지정단위기간) 단위의 단일가매매로 거래가 재개됩니다.";
    } else if (cmb_RegistType.BindColVal === "1") {
        // 매매거래정지 해제
        remk = "상기 종목은 매매거래정지 사유가 해소됨에 따라 매매거래정지가 해제되며,\r\n" + "매매거래정지해제일부터 투자유의종목으로서 3매매거래일(지정단위기간) 단위의 단일가매매로 거래가 재개됩니다.";
    } else if (cmb_RegistType.BindColVal === "2") {
        // 매매거래정지 및 해제
        remk = "상기 종목은 투자유의종목 지정단위기간(3매매거래일)이 종료하는 날에 장종료시 실시간 괴리율이\r\n" + "규정상 의무범위의 3배 이상에 해당하여 1일간 매매거래가 정지됩니다.\r\n" + "매매거래정지해제일부터는 지정단위기간이 새롭게 시작되며, 단일가 매매로 거래가 재개됩니다\r\n\r\n" + "※ 시장상황급변 등 투자자보호 및 시장안정을 위해 매매거래정지 기간은 연장될 수 있습니다.";
    }
    arrPar[14] = remk;
    arrPar[15] = scwin.Isu_cd;
    arrPar[16] = scwin.Isu_nm;
    return arrPar.length;
};

/**
 * @method
 * @name getParUpdateTrdHalt
 * @description 매매거래정지  수정 파라메터
